) AS v(olympiad_profile_id, university_id, direction_id, admission_year, benefit, ege_min, diploma_grades, note, varies, source_id)
WHERE EXISTS (SELECT 1 FROM olympiad_profiles p WHERE p.id = v.olympiad_profile_id)
  AND EXISTS (SELECT 1 FROM university_directions ud
              WHERE ud.university_id = v.university_id AND ud.direction_id = v.direction_id)
ON CONFLICT (olympiad_profile_id, university_id, direction_id, admission_year) DO UPDATE SET
  benefit = EXCLUDED.benefit,
  ege_min = EXCLUDED.ege_min,
  diploma_grades = EXCLUDED.diploma_grades,
  note = EXCLUDED.note,
  varies = EXCLUDED.varies,
  source_id = EXCLUDED.source_id;

-- Объявление — событием «изменились льготы» на каждую льготу МФТИ с новой
-- оговоркой. Повторный прогон новых событий не пишет.
INSERT INTO content_changes (entity, entity_id, summary, detail)
SELECT 'benefit', b.olympiad_profile_id || '@' || b.university_id, 'benefits',
       jsonb_build_object('text', 'МФТИ объявил правила приёма 2027 года: БВИ дают только семь олимпиад РСОШ, порог ЕГЭ по профильному предмету — 85 баллов')
FROM benefits b
WHERE b.university_id = 'mipt' AND b.note LIKE '%С приёма 2027 года%'
  AND NOT EXISTS (SELECT 1 FROM content_changes c
                  WHERE c.entity = 'benefit' AND c.entity_id = b.olympiad_profile_id || '@' || b.university_id
                    AND c.detail->>'text' = 'МФТИ объявил правила приёма 2027 года: БВИ дают только семь олимпиад РСОШ, порог ЕГЭ по профильному предмету — 85 баллов');


